fn group_title(label: &str, color: Hsla, font: &str) -> impl IntoElement {
    let (long, short) = (RIBBON_BODY_HEIGHT, GROUP_TITLE_WIDTH);
    let escape = |text: &str| {
        text.replace('&', "&amp;")
            .replace('<', "&lt;")
            .replace('>', "&gt;")
            .replace('"', "&quot;")
    };
