        .absolute()
        .top((long - short) / 2.)
        .left((short - long) / 2.)
        .w(long)
        .h(short)
        .text_color(color)
        .with_transformation(Transformation::rotate(radians(-std::f32::consts::FRAC_PI_2)))
}""")
